using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;

public static class PaperRunnerAtlas {
    // Coordinates describe the supplied artwork on a 512 by 512 grid.
    // Normalize each cutout around the same pivot, pointing down in the atlas.
    public static void Stamp(Bitmap atlas, string path, int index, double ax, double ay,
                             double bx, double by, double scale, int[] outline, int[] interior,
                             int[] shoe, int highlight) {
        using (var image = new Bitmap(path)) {
            var bounds = new Rectangle(0, 0, image.Width, image.Height);
            var data = image.LockBits(bounds, ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            var pixels = new byte[data.Stride * data.Height];
            Marshal.Copy(data.Scan0, pixels, 0, pixels.Length);
            image.UnlockBits(data);
            double length = Math.Sqrt((bx-ax)*(bx-ax) + (by-ay)*(by-ay));
            double downX = (bx-ax)/length, downY = (by-ay)/length;
            for (int y=0; y<256; y++) for (int x=0; x<256; x++) {
                double u=(x-128)/scale, v=(y-76)/scale;
                double sx=ax+downY*u+downX*v, sy=ay-downX*u+downY*v;
                if (shoe.Length >= 3) {
                    // Preserve the sole while foreshortening the profile of the toe.
                    double strength = Math.Max(0, Math.Min(1, (sy-shoe[1])/35));
                    double taper = 1-shoe[2]*.01*strength;
                    sx = shoe[0]+(sx-shoe[0])/taper;
                    if (shoe.Length == 4)
                        sy += strength * (sx-shoe[0]) * shoe[3] * .01;
                }
                double edge = Mask(outline,sx,sy);
                if (edge == 0 || sx < 0 || sy < 0 || sx >= 512 || sy >= 512) continue;
                int ix=(int)(sx*data.Width/512), iy=(int)(sy*data.Height/512);
                int i=iy*data.Stride+ix*4;
                double luma=.2126*pixels[i+2]+.7152*pixels[i+1]+.0722*pixels[i];
                // The source checkerboard is opaque. Convert ink density to alpha
                // so the washes and dry brush show the actual roof behind them.
                double density=Math.Pow(Math.Max(0, Math.Min(1, (232-luma)/218)),.9);
                double coverage=Math.Max(density, interior.Length == 0 ? 0 : .9*Mask(interior,sx,sy));
                int alpha=(int)Math.Round(255 * edge * coverage);
                // Light cloth and steel inside an enclosed silhouette are still
                // present. Keep their tone while letting the dry edges fade out.
                int ink=index==7 ? 58 : 27;
                int gray=coverage == 0 ? ink : (int)Math.Round(highlight-(highlight-ink)*density/coverage);
                if (alpha>0) atlas.SetPixel(index%4*256+x,index/4*256+y,
                                            Color.FromArgb(alpha, gray, gray, Math.Max(0,gray-3)));
            }
        }
    }

    private static double Mask(int[] points, double x, double y) {
        bool inside=false;
        double distance=double.MaxValue;
        for (int i=0, j=points.Length-2; i<points.Length; j=i, i+=2) {
            double ax=points[j], ay=points[j+1], bx=points[i], by=points[i+1];
            if ((ay>y)!=(by>y) && x<(bx-ax)*(y-ay)/(by-ay)+ax) inside=!inside;
            double dx=bx-ax, dy=by-ay;
            double t=Math.Max(0, Math.Min(1, ((x-ax)*dx+(y-ay)*dy)/(dx*dx+dy*dy)));
            double ex=x-ax-t*dx, ey=y-ay-t*dy;
            distance=Math.Min(distance,ex*ex+ey*ey);
        }
        return inside ? Math.Min(1, Math.Sqrt(distance)/5) : 0;
    }
}
'@

$atlas = [Drawing.Bitmap]::new(1024, 512, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
function Add-Part($name, $index, $ax, $ay, $bx, $by, $scale, $outline, $interior = @(), $shoe = @(), $highlight = 232) {
    [PaperRunnerAtlas]::Stamp($atlas,(Join-Path $source "$name.png"),$index,
        $ax,$ay,$bx,$by,$scale,$outline,$interior,$shoe,$highlight)
}
